package steps

import (
	"fmt"
	"strconv"
)

func phrase7c963587b98a9c9fa59fafbd25518c3af0d8d428753a4c888f114e5a06aa3242(state *State, args []string) error {
	// Given: store the number as the argument for the next `double` command
	// run, per the phrase mapping. No arithmetic happens here — the When runs
	// the declared CLI command and the Then compares its stdout.
	const zeroWord = "no"

	if len(args) != 1 {
		return fmt.Errorf("the number is {value:number}: expected 1 captured argument, got %d", len(args))
	}

	raw := args[0]
	number := 0
	if raw != zeroWord {
		parsed, err := strconv.Atoi(raw)
		if err != nil {
			return fmt.Errorf("the number is %q: not an integer: %w", raw, err)
		}
		number = parsed
	}

	state.Number = number
	state.NumberSet = true

	return nil
}

package steps

import (
	"fmt"
	"strconv"
)

func phraseed02cd0805872c6dc539a79f13857bcae5921c4b2ff964f4091e2a4a4e97246a(state *State, args []string) error {
	// Then: observe the result the When recorded and compare it with the
	// expected integer the Scenario states. The When already ran the declared
	// `double` command (docs/architecture/calc-cli.yaml) and kept its integer
	// stdout in state.Result, so nothing is run here and no arithmetic is
	// performed — the product computed the result, this step only compares it.
	const (
		phrase   = "the result is {value:number}"
		zeroWord = "no"
	)

	if len(args) != 1 {
		return fmt.Errorf("%s: expected 1 captured argument, got %d", phrase, len(args))
	}
	if !state.ResultSet {
		return fmt.Errorf("%s: no result recorded; a When must double the number first", phrase)
	}

	raw := args[0]
	expected := 0
	if raw != zeroWord {
		parsed, err := strconv.Atoi(raw)
		if err != nil {
			return fmt.Errorf("the result is %q: not an integer: %w", raw, err)
		}
		expected = parsed
	}

	if state.Result != expected {
		return fmt.Errorf(
			"the result is %d, but the double command printed %d",
			expected, state.Result,
		)
	}

	return nil
}

package steps

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
)

func phrasefd1683cb9efb040dcb9ff323bbe5d2d3e9f958d39b3e3e7eafcb136f94b8a9df(state *State, args []string) error {
	// When: run the declared `double` command as a process and keep its
	// integer stdout. Per docs/architecture/calc-cli.yaml the command is
	// `go run ./services/calc double VALUE`, run from the host root, and its
	// stdout is the doubled integer plus a newline. No arithmetic happens
	// here — the product computes the result, this step only observes it.
	const phrase = "the number is doubled"

	if len(args) != 0 {
		return fmt.Errorf("%s: expected 0 captured arguments, got %d", phrase, len(args))
	}
	if !state.NumberSet {
		return fmt.Errorf("%s: no number supplied; a Given must state the number first", phrase)
	}

	workdir, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("%s: working directory: %w", phrase, err)
	}

	// The host root is the directory holding go.mod, which is where the
	// declared `go run ./services/calc ...` invocation is rooted.
	hostRoot := ""
	for probe := workdir; ; {
		if _, statErr := os.Stat(filepath.Join(probe, "go.mod")); statErr == nil {
			hostRoot = probe
			break
		}
		parent := filepath.Dir(probe)
		if parent == probe {
			break
		}
		probe = parent
	}
	if hostRoot == "" {
		return fmt.Errorf("%s: no host root (a directory with go.mod) found at or above %s", phrase, workdir)
	}

	value := strconv.Itoa(state.Number)
	cmd := exec.Command("go", "run", "./services/calc", "double", value)
	cmd.Dir = hostRoot
	cmd.Env = os.Environ()

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if runErr := cmd.Run(); runErr != nil {
		return fmt.Errorf(
			"%s: `go run ./services/calc double %s` in %s failed: %w (stderr: %s)",
			phrase, value, hostRoot, runErr, strings.TrimSpace(stderr.String()),
		)
	}

	printed := strings.TrimSpace(stdout.String())
	result, convErr := strconv.Atoi(printed)
	if convErr != nil {
		return fmt.Errorf(
			"%s: `go run ./services/calc double %s` printed %q, not an integer: %w",
			phrase, value, printed, convErr,
		)
	}

	state.Result = result
	state.ResultSet = true

	return nil
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("\\Athe number is ((?:[0-9]+|no))\\z", phrase7c963587b98a9c9fa59fafbd25518c3af0d8d428753a4c888f114e5a06aa3242)

	suite.Step("\\Athe number is doubled\\z", phrasefd1683cb9efb040dcb9ff323bbe5d2d3e9f958d39b3e3e7eafcb136f94b8a9df)

	suite.Step("\\Athe result is ((?:[0-9]+|no))\\z", phraseed02cd0805872c6dc539a79f13857bcae5921c4b2ff964f4091e2a4a4e97246a)
}

package steps

type State struct {
	// Number is the integer argument the next `double` command run receives,
	// stored by the `the number is {value:number}` Given.
	Number int
	// NumberSet reports whether a Given has supplied Number yet.
	NumberSet bool
	// Result is the integer stdout of the last `double` command run, kept by
	// the `the number is doubled` When for the Then to compare.
	Result int
	// ResultSet reports whether a When has run `double` and recorded Result.
	ResultSet bool
}
